// stmt → 'print' expr ';' | '{' block '}'
function stmt(): Node {
	if (peek().type === "PRINT") {
		advance();
		const value = expr();
		expect("SEMICOLON");
		return { kind: "print", value };
	}
	expect("LBRACE");
	const body = block();
	expect("RBRACE");
	return body;
}

