function parseExpr(minPower: number): Node {
	let left = parsePrimary();
	while (power(peek()) > minPower) {
		const op = advance();
		// Left-associative: the right operand may not take an operator of the same power.
		const right = parseExpr(power(op));
		left = { kind: "binary", op, left, right };
	}
	return left;
}

